$msg=''; if(isset($_POST['save'])){ csrf_verify(); $pdo->prepare('UPDATE registrations SET name=?,semester=?,batch=?,reg_no=?,designation=?,mobile=?,reference=? WHERE id=?')->execute([trim($_POST['name']),trim($_POST['semester'])?:null,trim($_POST['batch'])?:null,trim($_POST['reg_no'])?:null,trim($_POST['designation'])?:null,trim($_POST['mobile']),trim($_POST['reference'])?:null,$id]); $msg='Registration updated by admin.'; $st->execute([$id]); $r=$st->fetch(); }
