?><!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Edit Registration</title><link rel="stylesheet" href="../assets/style.css"></head><body><main class="container"><div class="panel" style="max-width:650px;margin:40px auto"><h2>Edit Registration</h2><p style="color:var(--muted)"><?=v('title')?> · <?=strtoupper(e($r['role']))?></p><?php if($msg):?><div class="alert alert-ok"><?=$msg?></div><?php endif;?><form method="post"><?=csrf_field()?><div class="field"><label>Name *</label><input name="name" required value="<?=v('name')?>"></div><div class="form-row"><div class="field"><label>Semester</label><input name="semester" value="<?=v('semester')?>"></div><div class="field"><label>Batch</label><input name="batch" value="<?=v('batch')?>"></div></div><div class="form-row"><div class="field"><label>Registration No.</label><input name="reg_no" value="<?=v('reg_no')?>"></div><div class="field"><label>Mobile *</label><input name="mobile" required value="<?=v('mobile')?>"></div></div><div class="field"><label>Designation</label><input name="designation" value="<?=v('designation')?>"></div><div class="field"><label>Reference</label><input name="reference" value="<?=v('reference')?>"></div><button class="btn btn-primary" name="save" value="1">Save Changes</button> <a class="btn" href="registrations.php?event=<?=$r['event_id']?>">Back</a></form></div></main></body></html>